create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key references auth.users on delete cascade, nickname text unique not null, role text not null default 'user' check(role in ('user','admin')), created_at timestamptz default now());
create table if not exists wiki_entries (id uuid primary key default gen_random_uuid(), slug text unique not null, category text not null, title text not null, summary text, body text not null default '', image_url text, updated_at timestamptz default now());
create table if not exists guides (id uuid primary key default gen_random_uuid(), author_id uuid not null references profiles(id) on delete cascade, title text not null, body text not null, image_url text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists questions (id uuid primary key default gen_random_uuid(), author_id uuid not null references profiles(id) on delete cascade, title text not null, body text not null, image_url text, accepted_answer_id uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists answers (id uuid primary key default gen_random_uuid(), question_id uuid not null references questions(id) on delete cascade, author_id uuid not null references profiles(id) on delete cascade, body text not null, image_url text, created_at timestamptz default now());
do $$ begin if not exists(select 1 from pg_constraint where conname='accepted_answer_fk') then alter table questions add constraint accepted_answer_fk foreign key (accepted_answer_id) references answers(id) on delete set null; end if; end $$;
create table if not exists content_wiki_links (id bigint generated always as identity primary key, wiki_id uuid references wiki_entries(id) on delete cascade, guide_id uuid references guides(id) on delete cascade, question_id uuid references questions(id) on delete cascade, check ((guide_id is not null)::int + (question_id is not null)::int = 1));
create table if not exists votes (id bigint generated always as identity primary key, user_id uuid references profiles(id) on delete cascade, guide_id uuid references guides(id) on delete cascade, answer_id uuid references answers(id) on delete cascade, value smallint not null check(value in (-1,1)));
create unique index if not exists votes_guide_unique on votes(user_id,guide_id) where guide_id is not null;
create unique index if not exists votes_answer_unique on votes(user_id,answer_id) where answer_id is not null;
create table if not exists search_events (id bigint generated always as identity primary key, user_id uuid references profiles(id), query text not null, created_at timestamptz default now());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,nickname) values(new.id, coalesce(nullif(new.raw_user_meta_data->>'nickname',''),'CatHero-'||substr(new.id::text,1,6))); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

alter table profiles enable row level security; alter table wiki_entries enable row level security; alter table guides enable row level security; alter table questions enable row level security; alter table answers enable row level security; alter table content_wiki_links enable row level security; alter table votes enable row level security; alter table search_events enable row level security;
create policy "profiles readable" on profiles for select using(true); create policy "own profile update" on profiles for update using(auth.uid()=id);
create policy "wiki readable" on wiki_entries for select using(true); create policy "admin wiki insert" on wiki_entries for insert with check(exists(select 1 from profiles where id=auth.uid() and role='admin')); create policy "admin wiki update" on wiki_entries for update using(exists(select 1 from profiles where id=auth.uid() and role='admin')); create policy "admin wiki delete" on wiki_entries for delete using(exists(select 1 from profiles where id=auth.uid() and role='admin'));
create policy "guides readable" on guides for select using(true); create policy "guides own insert" on guides for insert with check(auth.uid()=author_id); create policy "guides own update" on guides for update using(auth.uid()=author_id); create policy "guides own delete" on guides for delete using(auth.uid()=author_id);
create policy "questions readable" on questions for select using(true); create policy "questions own insert" on questions for insert with check(auth.uid()=author_id); create policy "questions own update" on questions for update using(auth.uid()=author_id); create policy "questions own delete" on questions for delete using(auth.uid()=author_id);
create policy "answers readable" on answers for select using(true); create policy "answers own insert" on answers for insert with check(auth.uid()=author_id); create policy "answers own update" on answers for update using(auth.uid()=author_id); create policy "answers own delete" on answers for delete using(auth.uid()=author_id);
create policy "links readable" on content_wiki_links for select using(true); create policy "links authenticated insert" on content_wiki_links for insert to authenticated with check(true); create policy "links authenticated delete" on content_wiki_links for delete to authenticated using(true);
create policy "votes readable" on votes for select using(true); create policy "votes own insert" on votes for insert with check(auth.uid()=user_id); create policy "votes own delete" on votes for delete using(auth.uid()=user_id);
create policy "search insert" on search_events for insert with check(user_id is null or auth.uid()=user_id);

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('community-images','community-images',true,5242880,array['image/png','image/jpeg','image/webp','image/gif']) on conflict(id) do update set public=true;
create policy "community images public read" on storage.objects for select using(bucket_id='community-images');
create policy "community images authenticated upload" on storage.objects for insert to authenticated with check(bucket_id='community-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "community images owner delete" on storage.objects for delete to authenticated using(bucket_id='community-images' and (storage.foldername(name))[1]=auth.uid()::text);
-- Guides and Q&A intentionally receive NO seed rows.
